def copy_game_chats(apps, schema_editor):
    """Move each game's chat lines (the old ChatMessage table) into a "game:<id>" channel."""
    ChatMessage = apps.get_model("chat", "ChatMessage")
    Channel = apps.get_model("chat", "Channel")
    Message = apps.get_model("chat", "Message")
    for game_id in ChatMessage.objects.values_list("game_id", flat=True).distinct().order_by("game_id"):
        channel = Channel.objects.create(kind="game", key=f"game:{game_id}", game_id=game_id)
        rows = ChatMessage.objects.filter(game_id=game_id).order_by("id")
        Message.objects.bulk_create([
            Message(channel=channel, sender_id=r.user_id, name=r.name, colour=r.colour, seat=r.seat, text=r.text)
            for r in rows
        ])
        # bulk_create skips auto_now_add values we want to keep: copy the original times.
        new = list(Message.objects.filter(channel=channel).order_by("id"))
        for msg, old in zip(new, rows):
            msg.created_at = old.created_at
        Message.objects.bulk_update(new, ["created_at"])
        channel.last_message_id = new[-1].id if new else None
        channel.save(update_fields=["last_message_id"])


